const SAVE_KEY='ash-oath-save-v1';
const freshState=()=>({name:'Rowan Ashford',pronoun:'they',age:18,year:1008,month:3,gold:42,health:84,happiness:68,wisdom:32,reputation:12,renown:5,trait:'Hedge-born',title:'Commoner',home:'A room above the Copper Kettle',land:[],business:[],magic:{Ember:0,Tide:0,Green:0,Veil:0},inventory:[],affinity:'Mortal',alive:true,events:[{icon:'✦',text:'You came of age beneath the old ash tree. The world is waiting.',time:'Spring, Year 1008'}],people:[{name:'Mira Fen',role:'Apothecary’s apprentice',emoji:'🧝🏽‍♀️',relation:24,alive:true},{name:'Sir Aldric Vale',role:'Retired knight',emoji:'🧔🏻',relation:8,alive:true},{name:'Pip',role:'Your childhood friend',emoji:'🧑🏽',relation:38,alive:true}],flags:{},magicHistory:[],ending:false});
let S;try{S=JSON.parse(localStorage.getItem(SAVE_KEY))||freshState()}catch{S=freshState()}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=n=>Math.max(0,Math.min(100,n));const rand=a=>a[Math.floor(Math.random()*a.length)];
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(S))}
function log(text,icon='✦'){S.events.unshift({icon,text,time:`${['Spring','Summer','Autumn','Winter'][S.month%4]}, Year ${S.year}`});S.events=S.events.slice(0,8)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function adjust(key,amt){S[key]=key==='gold'?Math.max(0,S[key]+amt):clamp(S[key]+amt)}
function navTo(view){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>navTo(b.dataset.view));
function modal(title,desc,options){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true"><button class="close-modal" aria-label="Close">×</button><h2>${title}</h2><p>${desc}</p><div class="choices">${options.map((o,i)=>`<button class="choice" data-choice="${i}"><span>${o.label}</span><small>${o.note||''}</small></button>`).join('')}</div></div></div>`;root.querySelector('.close-modal').onclick=()=>root.innerHTML='';root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelectorAll('.choice').forEach((b,i)=>b.onclick=()=>{root.innerHTML='';options[i].run()})}
function update(){save();$('#yearTop').textContent=`Year ${S.year}`;$('#goldTop').textContent=`${S.gold} crowns`;$('#avatarMini').textContent=S.affinity==='Vampire'?'🧛':S.affinity==='Werewolf'?'🐺':'🧑🏻‍🌾';renderLife();renderRealm();renderArcana();renderPeople();renderCharacter()}
function meter(label,value,icon,color=''){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<span style="font:10px var(--sans);color:#929a8a"> / 100</span></div><div class="meter ${color}"><span style="width:${value}%"></span></div></div>`}
function eventHTML(){return S.events.length?S.events.slice(0,5).map(e=>`<div class="event"><div class="event-mark">${e.icon}</div><div class="event-text">${esc(e.text)}<time>${esc(e.time)}</time></div></div>`).join(''):'<p class="empty-note">Your chronicle begins here.</p>'}
function renderLife(){const heroLine=S.affinity==='Vampire'?'The night has claimed you. Your next chapter begins after dusk.':S.affinity==='Werewolf'?'The moon stirs beneath your skin. A wild path lies ahead.':`${S.title==='Commoner'?'A humble beginning, an unwritten fate.':`You are ${S.title.toLowerCase()}, and the realm knows your name.`}`;$('#view-life').innerHTML=`<div class="page-head"><div><div class="eyebrow">A living chronicle · ${S.month%4===0?'Spring':S.month%4===1?'Summer':S.month%4===2?'Autumn':'Winter'}</div><h1 class="page-title">Your life, ${esc(S.name.split(' ')[0])}</h1><p class="subtitle">Age ${S.age} · ${esc(S.title)} · ${esc(S.home)}</p></div><button class="year-button" onclick="advanceYear()">Live another year <span>→</span></button></div><div class="hero"><div class="hero-copy"><div class="hero-kicker">✦ &nbsp; A new chapter unfolds</div><h2>${S.affinity==='Mortal'?'The world is wider than you know.':'The old blood awakens.'}</h2><p>${heroLine} The choices you make will shape the person you become.</p><span class="origin-tag">✧ &nbsp; ${esc(S.trait)} <span style="color:#8f977f">·</span> ${esc(S.affinity)}</span></div><div class="hero-art"><div class="hero-symbol">${S.affinity==='Vampire'?'🌙':S.affinity==='Werewolf'?'🐺':'🌲'}</div></div></div><div class="stats">${meter('Health',S.health,'♡','red')}${meter('Happiness',S.happiness,'☼','gold')}${meter('Wisdom',S.wisdom,'✧')}${meter('Renown',S.renown,'♜','gold')}</div><div class="layout"><div><div class="section-row"><h2 class="section-title">Shape your days</h2><span style="font-size:10px;color:#8e9785">Choose a path</span></div><div class="panel"><div class="action-grid"><button class="action" onclick="studyAction()"><span class="action-icon">📖</span><b>Study & train</b><small>Grow your mind or master a craft</small></button><button class="action" onclick="workAction()"><span class="action-icon">⚒️</span><b>Earn a living</b><small>Find work and gather crowns</small></button><button class="action" onclick="socialAction()"><span class="action-icon">🍷</span><b>Spend an evening</b><small>Rest, celebrate, or make a friend</small></button><button class="action" onclick="exploreAction()"><span class="action-icon">🧭</span><b>Explore the wilds</b><small>Seek fortune beyond the village</small></button></div></div></div><div class="right-column"><div><div class="section-row"><h2 class="section-title">Recent moments</h2></div><div class="panel"><div class="event-list">${eventHTML()}</div></div></div><div><div class="section-row"><h2 class="section-title">Your standing</h2></div><div class="panel"><div class="event-list"><div class="event"><div class="event-mark">♜</div><div class="event-text">${esc(S.title)}<time>Rank in the realm</time></div></div><div class="event"><div class="event-mark">◈</div><div class="event-text">${S.gold} crowns<time>Personal fortune</time></div></div><div class="event"><div class="event-mark">⌂</div><div class="event-text">${S.land.length} holdings · ${S.business.length} ventures<time>Your legacy</time></div></div></div></div></div></div></div><div class="columns"><div class="panel"><div class="section-row"><h2 class="section-title">Those close to you</h2><button class="tiny-link" onclick="navTo('people')">See all →</button></div>${S.people.filter(p=>p.alive).slice(0,2).map(personHTML).join('')||'<p class="empty-note">You walk alone—for now.</p>'}</div><div class="panel"><div class="section-row"><h2 class="section-title">A note from the scribe</h2></div><p class="empty-note">There is no single road through the Northern Marches. Make a fortune, study the hidden arts, earn a title—or simply see what the next sunrise brings.</p></div></div>`}
function personHTML(p){return `<div class="person-row"><div class="person-face">${p.emoji}</div><div class="person-info"><b>${esc(p.name)}</b><small>${esc(p.role)}</small></div><span class="relation">♡ ${p.relation}</span></div>`}
function studyAction(){modal('What will you study?','A little knowledge can open unexpected doors.',[{label:'Read at the village scriptorium',note:'Wisdom +8 · 4 crowns',run:()=>{if(S.gold<4)return toast('You need 4 crowns for the scriptorium.');S.gold-=4;adjust('wisdom',8);adjust('happiness',2);log('You spent the afternoon among dusty books at the scriptorium.','📖');update()}},{label:'Train with the retired knight',note:'Health +5 · Renown +3',run:()=>{adjust('health',5);adjust('renown',3);log('Sir Aldric showed you the basics of sword and shield.','⚔️');update()}},{label:'Practice a little magic',note:'Wisdom +3 · discover Arcana',run:()=>{adjust('wisdom',3);S.flags.triedMagic=true;log('A candle flame bent toward your hand. Perhaps there is magic in you after all.','✧');update();toast('A spark answers your call…')}}])}
function workAction(){modal('Find honest work','The village always needs a pair of willing hands.',[{label:'Help at the Copper Kettle',note:'+12 crowns · Happiness +2',run:()=>{S.gold+=12;adjust('happiness',2);log('You served a busy evening at the Copper Kettle and earned a fair wage.','🍺');update()}},{label:'Harvest the Fen family fields',note:'+9 crowns · Health +3',run:()=>{S.gold+=9;adjust('health',3);log('The harvest was good. Mira slipped you an extra loaf for your hard work.','🌾');S.people[0].relation=clamp(S.people[0].relation+3);update()}},{label:'Carry a merchant’s sealed parcel',note:'+20 crowns · A little risky',run:()=>{S.gold+=20;let msg=Math.random()<.25?'The city watch questioned you about the parcel. Your reputation took a hit.':'The delivery went smoothly. The merchant paid generously.';if(msg.includes('watch'))adjust('reputation',-3);else adjust('reputation',1);log(msg,'📦');update()}}])}
function socialAction(){modal('How shall you spend the evening?','Small joys matter as much as grand ambitions.',[{label:'Share supper with Pip',note:'Happiness +8 · Friendship grows',run:()=>{adjust('happiness',8);S.people[2].relation=clamp(S.people[2].relation+10);log('You and Pip shared stories until the candles burned low.','🍲');update()}},{label:'Visit Mira at the apothecary',note:'Learn something useful',run:()=>{S.people[0].relation=clamp(S.people[0].relation+8);adjust('happiness',4);log('Mira showed you how to tell moonwort from common clover.','🌿');update()}},{label:'Take a quiet night in',note:'Health +9 · Happiness +3',run:()=>{adjust('health',9);adjust('happiness',3);log('You rested well, far from the noise of the tavern.','🌙');update()}}])}
function exploreAction(){modal('Where will curiosity lead?','The old paths hold things that never made it into the history books.',[{label:'Search the standing stones',note:'May reveal a magical gift',run:()=>{let r=Math.random();if(r<.34){S.flags.stones=true;S.magic.Green=Math.max(S.magic.Green,1);log('At the standing stones, green fire flickered in your palm. The land itself seemed to answer.','🌿');toast('Green magic awakened!')}else{S.gold+=6;log('You found a small purse beneath the stones—someone’s old offering.','◈')}update()}},{label:'Follow the river road',note:'A chance of treasure',run:()=>{if(Math.random()<.45){S.gold+=18;log('A broken cart by the river held a few forgotten crowns.','◈')}else{adjust('health',-5);log('A muddy fall on the river path left you sore but wiser.','🧭')}update()}},{label:'Ask about the moonlit cave',note:'A strange rumor',run:()=>{S.flags.caveRumor=true;log('A shepherd swears a pale stranger visits the cave when the moon is full.','🌙');update();navTo('arcana')}}])}
function advanceYear(){if(!S.alive)return toast('Your story has ended. Begin a new life from Character.');S.age++;S.year++;S.month=(S.month+1)%4;let msg;if(S.business.length){const income=S.business.reduce((a,b)=>a+b.income,0);S.gold+=income;msg=`Your ventures brought in ${income} crowns this year.`}else msg=rand(['A quiet year passes in the Northern Marches.','The seasons turn, and the village grows familiar.','Travelers brought strange tales from the southern kingdoms.','A hard winter tested everyone, but spring returned.']);if(S.age%5===0){adjust('health',-2);msg+=' The years are beginning to show.'}if(Math.random()<.18){let event=rand([{t:'A traveling storyteller filled the inn with songs of lost kings.',i:'🎻',h:3},{t:'A fever passed through the village. You recovered, though slowly.',i:'☘️',h:-7},{t:'You helped settle a dispute between neighbors. People trust you more.',i:'⚖️',r:4},{t:'A peddler sold you an odd charm that hums in moonlight.',i:'🌙',w:2}]);if(event.h)adjust('health',event.h);if(event.r)adjust('reputation',event.r);if(event.w){S.inventory.push('Moon-humming charm');S.flags.charm=true}msg+=' '+event.t}
if(S.affinity==='Vampire'&&Math.random()<.2)adjust('health',-4);if(S.health<=0){S.alive=false;msg='Your long journey has come to an end. The Marches remember you.';S.ending=true}log(msg,'⌛');update();toast(S.alive?`Welcome to Year ${S.year}.`:'Your chronicle has ended.')}

