function advanceYear(){if(!S.alive)return toast('Your story has ended. Begin a new life from Character.');S.age++;S.year++;S.month=(S.month+1)%4;let msg;if(S.business.length){const income=S.business.reduce((a,b)=>a+b.income,0);S.gold+=income;msg=`Your ventures brought in ${income} crowns this year.`}else msg=rand(['A quiet year passes in the Northern Marches.','The seasons turn, and the village grows familiar.','Travelers brought strange tales from the southern kingdoms.','A hard winter tested everyone, but spring returned.']);if(S.age%5===0){adjust('health',-2);msg+=' The years are beginning to show.'}if(Math.random()<.18){let event=rand([{t:'A traveling storyteller filled the inn with songs of lost kings.',i:'🎻',h:3},{t:'A fever passed through the village. You recovered, though slowly.',i:'☘️',h:-7},{t:'You helped settle a dispute between neighbors. People trust you more.',i:'⚖️',r:4},{t:'A peddler sold you an odd charm that hums in moonlight.',i:'🌙',w:2}]);if(event.h)adjust('health',event.h);if(event.r)adjust('reputation',event.r);if(event.w){S.inventory.push('Moon-humming charm');S.flags.charm=true}msg+=' '+event.t}if(S.affinity==='Vampire'&&Math.random()<.2)adjust('health',-4);if(S.health<=0){S.alive=false;msg='Your long journey has come to an end. The Marches remember you.';S.ending=true}log(msg,'⌛');update();toast(S.alive?`Welcome to Year ${S.year}.`:'Your chronicle has ended.')}
function renderRealm(){const landOffers=[['Fenland acre','🌾','A fertile field along the Fenwater.','35 crowns',35,'Makes a fine home or farm.'],['Old watchtower','🗼','A weatherworn tower above the village road.','55 crowns',55,'A symbol of standing—and a little mystery.'],['Pinewood rights','🌲','A small stretch of timber-rich woodland.','48 crowns',48,'A useful holding for any rising house.']];const bizOffers=[['Wayfarer’s Inn','🍺','A warm inn at the crossroads.','60 crowns',60,8],['Apothecary stall','⚗️','Sell remedies and curious tinctures.','48 crowns',48,6],['Miller’s wheel','⚙️','Grind grain for every village in the valley.','72 crowns',72,11]];const rankCost=S.title==='Commoner'?30:50;$('#view-realm').innerHTML=`<div class="page-head"><div><div class="eyebrow">A place to call your own</div><h1 class="page-title">The Realm</h1><p class="subtitle">Build a legacy in the Northern Marches.</p></div></div><div class="stats" style="margin:0 0 20px">${meter('Holdings',S.land.length,'⌂')}${meter('Ventures',S.business.length,'⚒️')}${meter('Reputation',S.reputation,'♧','gold')}${meter('Rank',Math.min(100,S.renown+(S.title==='Commoner'?0:20)),'♜','gold')}</div><div class="section-row"><h2 class="section-title">Land & holdings</h2><span style="font-size:10px;color:#929b8a">${S.land.length} owned</span></div><div class="cards-grid">${landOffers.map((x,i)=>`<article class="world-card"><span class="wc-icon">${x[1]}</span><div class="card-kicker">LAND · ${x[3]}</div><h3>${x[0]}</h3><p>${x[2]}</p><button ${S.gold<x[4]||S.land.includes(x[0])?'disabled':''} onclick="buyLand(${i})">${S.land.includes(x[0])?'Already owned':`Purchase · ${x[4]} ◈`}</button></article>`).join('')}</div><div class="section-row" style="margin-top:24px"><h2 class="section-title">A livelihood of your own</h2><span style="font-size:10px;color:#929b8a">Income on each new year</span></div><div class="cards-grid">${bizOffers.map((x,i)=>`<article class="world-card"><span class="wc-icon">${x[1]}</span><div class="card-kicker">BUSINESS · ${x[3]}</div><h3>${x[0]}</h3><p>${x[2]}</p><button ${S.gold<x[4]||S.business.some(b=>b.name===x[0])?'disabled':''} onclick="buyBusiness(${i})">${S.business.some(b=>b.name===x[0])?'Already owned':`Open · ${x[4]} ◈`}</button></article>`).join('')}</div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">The noble court</h2><span class="relation">${esc(S.title)}</span></div><p class="notice">Nobility is earned through deeds, standing, and the favor of the court. Build a reputation and bring a worthy offering.</p><div class="event"><div class="event-mark">♜</div><div class="event-text"><b style="color:#e9dfc5">Petition for a title</b><time>${S.title==='Commoner'?'Requires 30 crowns and reputation 25, or two land holdings.':S.title==='Landed Gentry'?'Earn more renown and petition for a higher title.':'Your title is recognized throughout the Marches.'}</time></div><button class="primary" style="margin:0" onclick="petitionTitle()" ${S.title==='Noble'?'disabled':''}>${S.title==='Noble'?'Highest rank':'Petition · '+rankCost+' ◈'}</button></div></div>`}
function buyLand(i){const offers=[['Fenland acre',35],['Old watchtower',55],['Pinewood rights',48]];let [name,cost]=offers[i];if(S.gold<cost)return toast('Not enough crowns.');if(S.land.includes(name))return toast('You already own this holding.');S.gold-=cost;S.land.push(name);adjust('renown',4);log(`You purchased ${name.toLowerCase()} and made it your own.`,'⌂');update();toast(`${name} is yours.`)}
function buyBusiness(i){const offers=[['Wayfarer’s Inn',60,8],['Apothecary stall',48,6],['Miller’s wheel',72,11]];let [name,cost,income]=offers[i];if(S.gold<cost)return toast('Not enough crowns.');if(S.business.some(b=>b.name===name))return toast('You already run this venture.');S.gold-=cost;S.business.push({name,income});adjust('reputation',3);log(`You opened the ${name}. It should bring in ${income} crowns each year.`,'⚒️');update();toast('Your new venture is open!')}
function petitionTitle(){if(S.title==='Noble')return toast('You already hold the highest title in the Marches.');let cost=S.title==='Commoner'?30:50;let qualified=S.title==='Commoner'?(S.reputation>=25||S.land.length>=2):S.renown>=35;if(!qualified)return toast(S.title==='Commoner'?'Earn 25 reputation or own two holdings to gain the court’s attention.':'Earn 35 renown before petitioning again.');if(S.gold<cost)return toast(`The court expects an offering of ${cost} crowns.`);S.gold-=cost;S.title=S.title==='Commoner'?'Landed Gentry':'Noble';adjust('renown',10);adjust('reputation',8);if(S.title==='Landed Gentry'&&!S.people.some(p=>p.name==='Lady Elowen'))S.people.push({name:'Lady Elowen',role:'Courtly patron',emoji:'👸🏻',relation:35,alive:true});log(`The court recognized you as ${S.title}. Your name now carries weight.`,'♜');update();toast(`You are now ${S.title}!`)}
function renderArcana(){const schools=[['Ember','🔥','The cinder arts','Warmth, light, and fierce defensive magic.'],['Tide','🌊','The flowing arts','Healing, patience, and the turning of fortune.'],['Green','🌿','The old root','Speak with growing things; mend what is broken.'],['Veil','🌙','The hidden arts','Listen to echoes, glamour, and the quiet dark.']];$('#view-arcana').innerHTML=`<div class="page-head"><div><div class="eyebrow">What sleeps beneath the world</div><h1 class="page-title">Arcana</h1><p class="subtitle">Magic is a craft, a calling, and sometimes a dangerous bargain.</p></div></div><div class="panel"><div class="section-row"><h2 class="section-title">The four paths</h2><span style="font-size:10px;color:#929b8a">Wisdom ${S.wisdom}</span></div><p class="notice">Study a path to unlock its gifts. Each lesson costs 8 crowns and grows more expensive with mastery.</p>${schools.map(([key,icon,title,desc])=>{let level=S.magic[key],cost=8+level*10;return `<div class="magic-row"><div class="magic-symbol">${icon}</div><div class="magic-info"><b>${title}</b><p>${desc}</p><div class="meter" style="max-width:170px;margin-top:8px"><span style="width:${Math.min(100,level*25)}%;background:#a98dd4"></span></div></div><span class="magic-level">${level?`Rank ${level}`:'Untrained'}</span><button class="primary" style="margin:0" onclick="learnMagic('${key}')" ${level>=4||S.gold<cost?'disabled':''}>${level>=4?'Mastered':`Learn · ${cost} ◈`}</button></div>`}).join('')}</div><div class="section-row" style="margin-top:23px"><h2 class="section-title">Beyond mortal bounds</h2></div><div class="cards-grid"><article class="world-card"><span class="wc-icon">🐺</span><div class="card-kicker">THE WILD BLOOD</div><h3>Moonbound</h3><p>Accept an ancient pact and discover what lives beneath your skin.</p><button onclick="seekChange('Werewolf')" ${S.affinity!=='Mortal'?'disabled':''}>${S.affinity==='Werewolf'?'Your nature':S.affinity!=='Mortal'?'Unavailable':'Seek the old pact'}</button></article><article class="world-card"><span class="wc-icon">🧛</span><div class="card-kicker">THE PALE COURT</div><h3>Nightborn</h3><p>Find the hidden cave and bargain with a creature of the long night.</p><button onclick="seekChange('Vampire')" ${S.affinity!=='Mortal'?'disabled':''}>${S.affinity==='Vampire'?'Your nature':S.affinity!=='Mortal'?'Unavailable':'Seek the night'}</button></article><article class="world-card"><span class="wc-icon">📜</span><div class="card-kicker">YOUR DISCOVERIES</div><h3>Field notes</h3><p>${S.magicHistory.length?S.magicHistory.join(' · '):'Your magical discoveries will be recorded here.'}</p><button onclick="castMagic()" ${Object.values(S.magic).every(x=>x===0)?'disabled':''}>Practice a spell</button></article></div>`}
function learnMagic(key){let level=S.magic[key],cost=8+level*10;if(level>=4)return toast('You have mastered this path.');if(S.gold<cost)return toast('Not enough crowns for that lesson.');S.gold-=cost;S.magic[key]++;S.wisdom=clamp(S.wisdom+2);let spells={Ember:'a spark that dances between your fingers',Tide:'a bead of water that mended a cracked cup',Green:'a sprout that unfurled in your palm',Veil:'a whisper from a shadow that knew your name'};let note=`You learned ${key}: ${spells[key]}.`;S.magicHistory.unshift(note);log(note,'✧');update();toast(`${key} magic · Rank ${S.magic[key]}`)}
function castMagic(){let ready=Object.entries(S.magic).filter(([,n])=>n>0);if(!ready.length)return toast('Learn a magical path first.');modal('Practice a spell','A little practice sharpens your gift.',ready.map(([key,level])=>({label:`${key} · Rank ${level}`,note:key==='Tide'?'Restore health':key==='Ember'?'A flare of harmless light':key==='Green'?'Nurture a seedling':'A brief glamour',run:()=>{if(key==='Tide')adjust('health',8);if(key==='Ember')adjust('happiness',3);if(key==='Green')adjust('happiness',5);if(key==='Veil')adjust('wisdom',3);log(`You practiced ${key.toLowerCase()} magic. The spell came more easily this time.`,'✧');update();toast(`${key} magic practiced.`)}})))}
function seekChange(kind){if(S.affinity!=='Mortal')return;if(kind==='Werewolf'){if(!S.flags.stones)return modal('The old pact','The moonbound are said to gather at the standing stones. First, explore the wilds and seek their sign.',[{label:'I will look for the stones',note:'Return to your life',run:()=>navTo('life')}]);modal('A pact beneath the moon','The stones recognize you. The pact will change your life—there is no turning back.',[{label:'Accept the wild blood',note:'Become Moonbound',run:()=>{S.affinity='Werewolf';S.health=clamp(S.health+10);S.magic.Green=Math.max(1,S.magic.Green);log('Beneath the standing stones, you accepted the moonbound pact. The wild answered.','🐺');update();toast('You are Moonbound.')}}])}else{if(!S.flags.caveRumor)return modal('A rumor in the tavern','A shepherd told you of a cave where pale eyes watch the moon. Ask around or explore the river road to find a lead.',[{label:'Ask around the village',note:'Mark the rumor in your journal',run:()=>{S.flags.caveRumor=true;log('You heard a rumor about a pale stranger in a moonlit cave.','🌙');update();toast('Rumor added to your field notes.')}}]);modal('The pale stranger','A graceful figure offers immortality in exchange for a promise: keep the secret of the night. Do you accept?',[{label:'Drink from the crimson cup',note:'Become Nightborn · health +12',run:()=>{S.affinity='Vampire';S.health=clamp(S.health+12);S.magic.Veil=Math.max(1,S.magic.Veil);log('You accepted the pale stranger’s offer. Night opened its endless door.','🧛');update();toast('You are Nightborn.')}}])}}

