function seekChange(kind){if(S.affinity!=='Mortal')return;if(kind==='Werewolf'){if(!S.flags.stones)return modal('The old pact','The moonbound are said to gather at the standing stones. First, explore the wilds and seek their sign.',[{label:'I will look for the stones',note:'Return to your life',run:()=>navTo('life')}]);modal('A pact beneath the moon','The stones recognize you. The pact will change your life—there is no turning back.',[{label:'Accept the wild blood',note:'Become Moonbound',run:()=>{S.affinity='Werewolf';S.health=clamp(S.health+10);S.magic.Green=Math.max(1,S.magic.Green);log('Beneath the standing stones, you accepted the moonbound pact. The wild answered.','🐺');update();toast('You are Moonbound.')}}])}else{if(!S.flags.caveRumor)return modal('A rumor in the tavern','A shepherd told you of a cave where pale eyes watch the moon. Ask around or explore the river road to find a lead.',[{label:'Ask around the village',note:'Mark the rumor in your journal',run:()=>{S.flags.caveRumor=true;log('You heard a rumor about a pale stranger in a moonlit cave.','🌙');update();toast('Rumor added to your field notes.')}}]);modal('The pale stranger','A graceful figure offers immortality in exchange for a promise: keep the secret of the night. Do you accept?',[{label:'Drink from the crimson cup',note:'Become Nightborn · health +12',run:()=>{S.affinity='Vampire';S.health=clamp(S.health+12);S.magic.Veil=Math.max(1,S.magic.Veil);log('You accepted the pale stranger’s offer. Night opened its endless door.','🧛');update();toast('You are Nightborn.')}}])}}
function renderPeople(){$('#view-people').innerHTML=`<div class="page-head"><div><div class="eyebrow">Allies, rivals & chance encounters</div><h1 class="page-title">Your people</h1><p class="subtitle">Every relationship is a story in the making.</p></div></div><div class="panel"><div class="section-row"><h2 class="section-title">Known to you</h2><span style="font-size:10px;color:#929b8a">${S.people.filter(p=>p.alive).length} in your circle</span></div>${S.people.map((p,i)=>p.alive?`<div class="person-row"><div class="person-face">${p.emoji}</div><div class="person-info"><b>${esc(p.name)}</b><small>${esc(p.role)} · ${p.relation<20?'Acquaintance':p.relation<55?'Friend':'Close friend'}</small><div class="meter" style="max-width:180px;margin-top:7px"><span style="width:${p.relation}%;background:${p.relation<20?'#bc826f':'#a7bd8e'}"></span></div></div><span class="relation">♡ ${p.relation}</span><button class="primary" style="margin:0" onclick="talkTo(${i})">Talk</button></div>`:`<div class="person-row" style="opacity:.5"><div class="person-face">🕯️</div><div class="person-info"><b>${esc(p.name)}</b><small>No longer among the living</small></div></div>`).join('')||'<p class="empty-note">You have not met anyone yet. Try the village tavern.</p>'}</div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">Choices have consequences</h2></div><p class="notice">You can be kind, cruel, or somewhere in between. The Marches are small; word travels. Harm done to another person may haunt your conscience and your reputation.</p></div>`}
function talkTo(i){let p=S.people[i];if(!p||!p.alive)return toast('You cannot speak with them.');modal(`Speak with ${esc(p.name)}`,`${esc(p.role)} · Friendship ${p.relation}/100`,[{label:'Share a kind word',note:'Friendship +8 · Happiness +2',run:()=>{p.relation=clamp(p.relation+8);adjust('happiness',2);log(`You shared a warm conversation with ${p.name}.`,'♡');update()}},{label:'Ask for advice',note:'Wisdom +2 · Friendship +3',run:()=>{p.relation=clamp(p.relation+3);adjust('wisdom',2);log(`${p.name} shared a useful bit of advice with you.`,'💬');update()}},{label:'Offer a small gift',note:'Costs 8 crowns · Friendship +15',run:()=>{if(S.gold<8)return toast('You need 8 crowns for a thoughtful gift.');S.gold-=8;p.relation=clamp(p.relation+15);log(`You gave ${p.name} a thoughtful gift.`,'🎁');update()}},{label:'Start a quarrel',note:'Risky · may damage your standing',run:()=>{p.relation=clamp(p.relation-18);adjust('reputation',-2);log(`A heated argument with ${p.name} left hard feelings on both sides.`,'⚡');update()}},{label:'Challenge to a duel',note:'Dangerous · could injure either of you',run:()=>{let win=Math.random()<.45+(S.health/400);adjust('health',-8);if(win){adjust('renown',4);p.relation=clamp(p.relation-22);log(`You won a public duel with ${p.name}. The crowd cheered, but the friendship suffered.`,'⚔️')}else{adjust('health',-12);p.relation=clamp(p.relation-10);log(`You lost a duel with ${p.name} and left with bruises and a humbled pride.`,'⚔️')}update()}},{label:'Plot their death',note:'Dark choice · great risk, lasting consequences',run:()=>{modal('A terrible choice','The act would be deliberate and irreversible. If discovered, the law and the people may turn against you.',[{label:'Go through with it',note:'They will be gone; your conscience and standing suffer',run:()=>{p.alive=false;p.relation=0;adjust('happiness',-12);adjust('reputation',-18);adjust('renown',2);let caught=Math.random()<.42;if(caught){adjust('reputation',-20);log(`${p.name} was killed. Witnesses named you to the reeve; the Marches will not forget.`,'☠️');toast('The reeve has begun asking questions.')}else{log(`${p.name} was killed. No one can prove what happened, but the silence weighs on you.`,'☠️');toast('A choice you cannot undo.')};update()}},{label:'Step away',note:'No one is harmed',run:()=>toast('You chose not to cross that line.') }])}}])}
function renderCharacter(){$('#view-character').innerHTML=`<div class="page-head"><div><div class="eyebrow">The person behind the choices</div><h1 class="page-title">Character</h1><p class="subtitle">Your origins, gifts, and everything you have built.</p></div></div><div class="panel"><div class="profile-head"><div class="portrait">${S.affinity==='Vampire'?'🧛':S.affinity==='Werewolf'?'🐺':'🧑🏻‍🌾'}</div><div><h2>${esc(S.name)}</h2><p>Age ${S.age} · ${esc(S.title)} · ${esc(S.affinity)}</p></div></div><div class="detail-grid"><div class="detail"><span>Origin</span><b>${esc(S.trait)}</b></div><div class="detail"><span>Home</span><b>${esc(S.home)}</b></div><div class="detail"><span>Fortune</span><b>${S.gold} crowns</b></div><div class="detail"><span>Reputation</span><b>${S.reputation} / 100</b></div><div class="detail"><span>Land</span><b>${S.land.length} holdings</b></div><div class="detail"><span>Businesses</span><b>${S.business.length} ventures</b></div></div></div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">Your belongings</h2></div><p class="empty-note">${S.inventory.length?S.inventory.map(esc).join(' · '):'Just the clothes on your back—and whatever you make of this life.'}</p></div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">The chronicle</h2></div><div class="event-list">${S.events.map(e=>`<div class="event"><div class="event-mark">${e.icon}</div><div class="event-text">${esc(e.text)}<time>${esc(e.time)}</time></div></div>`).join('')}</div></div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">Your story, your way</h2></div><p class="notice">Rename your character or begin a completely new life. Starting over clears this device’s saved chronicle.</p><button class="primary" onclick="renameCharacter()">Choose a name</button> <button class="primary" onclick="newLife()">Begin a new life</button></div>`}
function renameCharacter(){let name=prompt('What name will the Marches know you by?',S.name);if(name&&name.trim()){S.name=name.trim().slice(0,35);log(`You chose the name ${S.name}.`,'✧');update();toast('Name updated.')}}
function newLife(){modal('Begin again?','This will erase your current chronicle from this device and create a fresh character.',[{label:'Start a new life',note:'Your current save will be replaced',run:()=>{S=freshState();update();navTo('life');toast('A new story begins.')}},{label:'Keep this life',note:'Return to your chronicle',run:()=>{}}])}
update();

