on></article><article class="world-card"><span class="wc-icon">🧛</span><div class="card-kicker">THE PALE COURT</div><h3>Nightborn</h3><p>Find the hidden cave and bargain with a creature of the long night.</p><button onclick="seekChange('Vampire')" ${S.affinity!=='Mortal'?'disabled':''}>${S.affinity==='Vampire'?'Your nature':S.affinity!=='Mortal'?'Unavailable':'Seek the night'}</button></article><article class="world-card"><span class="wc-icon">📜</span><div class="card-kicker">YOUR DISCOVERIES</div><h3>Field notes</h3><p>${S.magicHistory.length?S.magicHistory.join(' · '):'Your magical discoveries will be recorded here.'}</p><button onclick="castMagic()" ${Object.values(S.magic).every(x=>x===0)?'disabled':''}>Practice a spell</button></article></div>`}
 function learnMagic(key){let level=S.magic[key],cost=8+level*10;if(level>=4)return toast('You have mastered this path.');if(S.gold<cost)return toast('Not enough crowns for that lesson.');S.gold-=cost;S.magic[key]++;S.wisdom=clamp(S.wisdom+2);let spells={Ember:'a spark that dances between your fingers',Tide:'a bead of water that mended a cracked cup',Green:'a sprout that unfurled in your palm',Veil:'a whisper from a shadow that knew your name'};let note=`You learned ${key}: ${spells[key]}.`;S.magicHistory.unshift(note);log(note,'✧');update();toast(`${key} magic · Rank ${S.magic[key]}`)}
