const SKILL_META={Combat:['⚔️','Weapons, tactics, and command'],Scholarship:['📚','Lore, letters, and careful study'],Commerce:['◈','Trade, bargaining, and enterprise'],Stewardship:['🏰','Managing estates and resources'],Diplomacy:['🤝','Courtly speech and negotiation'],Survival:['🧭','Tracking, hunting, and wilderness craft'],Crafting:['🔨','Making useful tools and fine goods'],Social:['♡','Friendship, empathy, and influence'],Destruction:['🔥','Elemental force and direct magical attacks'],Conjuration:['🜂','Summoning allies and bound arms'],Alteration:['✧','Shaping matter, protection, and the body'],Restoration:['☼','Healing, wards, and renewal'],Necromancy:['☠️','Communing with the dead and raising servants'],Illusion:['🌫️','Glamour, misdirection, and the mind'],Spatial:['🌀','Distance, portals, and folded space'],Blood:['🩸','Vitality, sacrifice, and sanguine rites'], 'Dark Magic':['🌑','Curses, shadows, and forbidden power']};
function skillCost(name){return Math.min(1000000,12+(S.skills[name]||0)*6)}
function trainSkill(name){if(!SKILL_NAMES.includes(name))return;if(S.gold<skillCost(name))return toast(`You need ${skillCost(name)} crowns to study ${name}.`);let cost=skillCost(name);S.gold-=cost;S.skills[name]=(S.skills[name]||0)+1;if(['Destruction','Conjuration','Alteration','Restoration','Necromancy','Illusion','Spatial','Blood','Dark Magic'].includes(name))S.wisdom=clamp(S.wisdom+1);log(`You trained ${name} to rank ${S.skills[name]}.`,'✧');update();toast(`${name} · Rank ${S.skills[name]}`)}
function skillCard(name){let [icon,desc]=SKILL_META[name],rank=S.skills[name]||0,cost=skillCost(name);return `<article class="skill-card"><div class="skill-head"><span>${icon}</span><b>${name}</b><strong>Rank ${rank}</strong></div><p>${desc}</p><div class="meter"><span style="width:${Math.min(100,rank%10*10)}%;background:#a98dd4"></span></div><button class="primary" onclick="trainSkill('${name}')" ${S.gold<cost?'disabled':''}>Train · ${cost} ◈</button></article>`}
function updateAppearance(key,value){if(key==='name'){let n=value.trim();if(n)S.name=n.slice(0,35)}else if(['gender','bodyType','hairLength','hairstyle'].includes(key))S[key]=value;else if(key==='hairColor'||key==='eyeColor'){if(/^#[0-9a-f]{6}$/i.test(value))S[key]=value}if(key==='gender')S.pronoun=value==='Woman'?'she':value==='Man'?'he':'they';update()}
function renderCharacter(){renderCharacterLegacy();const appearance=`<div class="panel wide-panel"><div class="section-row"><h2 class="section-title">Shape your character</h2><span class="tiny-note">Changes save automatically</span></div><p class="notice">Choose the look and identity that feel right. These choices do not restrict your story or abilities.</p><div class="creator-grid"><label class="field">Name<input value="${esc(S.name)}" maxlength="35" onchange="updateAppearance('name',this.value)" autocomplete="off"></label><label class="field">Gender<select onchange="updateAppearance('gender',this.value)">${['Woman','Man','Nonbinary','Genderfluid','Other'].map(v=>`<option ${S.gender===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Body type<select onchange="updateAppearance('bodyType',this.value)">${['Petite','Lean','Average','Athletic','Broad','Soft'].map(v=>`<option ${S.bodyType===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Hair length<select onchange="updateAppearance('hairLength',this.value)">${['Shaved','Short','Shoulder-length','Long','Very long'].map(v=>`<option ${S.hairLength===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Hairstyle<select onchange="updateAppearance('hairstyle',this.value)">${['Loose waves','Straight','Braided','Curly','Tied back','Undercut','Cropped'].map(v=>`<option ${S.hairstyle===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field color-field">Hair color<input type="color" value="${S.hairColor}" onchange="updateAppearance('hairColor',this.value)"></label><label class="field color-field">Eye color<input type="color" value="${S.eyeColor}" onchange="updateAppearance('eyeColor',this.value)"></label></div><div class="appearance-summary"><span class="appearance-dot" style="--hair:${S.hairColor};--eyes:${S.eyeColor}">◉</span><span><b>${esc(S.gender)} · ${esc(S.bodyType)}</b><small>${esc(S.hairLength)} ${esc(S.hairstyle.toLowerCase())} · custom hair and eye colors</small></span></div></div><div class="panel wide-panel"><div class="section-row"><h2 class="section-title">Skill trees</h2><span class="tiny-note">No level cap · crowns fund training</span></div><p class="notice">Every rank strengthens your growing talents. Train any path whenever you can afford its lesson; costs rise gradually, with no maximum rank.</p><h3 class="tree-heading">Life & calling</h3><div class="skill-grid">${SKILL_NAMES.slice(0,8).map(skillCard).join('')}</div><h3 class="tree-heading">Arcane disciplines</h3><div class="skill-grid">${SKILL_NAMES.slice(8).map(skillCard).join('')}</div></div>`;$('#view-character').innerHTML+=appearance}
