function recruitTroops(name,count,cost){let total=count*cost;if(S.gold<total)return toast('You cannot afford those recruits.');S.gold-=total;let t=S.army.troops.find(x=>x.name===name);if(t)t.count+=count;else S.army.troops.push({name,count});S.army.morale=Math.min(100,S.army.morale+2);log(`You recruited ${count} ${name.toLowerCase()} to your banner.`,'⚔️');update();toast(`${count} ${name} recruited.`)}
