async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  const initial = await page.evaluate(() => ({
    title: document.title,
    view: document.querySelector('#view-life').innerText.slice(0, 100),
    gold: S.gold,
    skillNames: SKILL_NAMES.slice(8),
    army: S.army
  }));
  await page.locator('[data-view="character"]').click();
  const creatorPresent = await page.locator('#view-character').getByText('Shape your character').count();
  const skillsPresent = await page.locator('#view-character').getByText('Dark Magic', {exact:true}).count();
  await page.locator('#view-character select').nth(0).selectOption('Woman');
  await page.locator('#view-character select').nth(1).selectOption('Athletic');
  await page.locator('#view-character input[type="color"]').nth(0).fill('#bb2244');
  await page.locator('#view-character button', {hasText:'Train · 12'}).first().click();
  await page.locator('#view-character').getByRole('button', {name:/Train ·/}).nth(8).click();
  const creatorState = await page.evaluate(() => ({gender:S.gender,body:S.bodyType,hair:S.hairColor,combat:S.skills.Combat,destruction:S.skills.Destruction,gold:S.gold}));
  await page.locator('[data-view="realm"]').click();
  await page.locator('#view-realm button', {hasText:'Recruit 5'}).first().click();
  await page.locator('#view-realm button', {hasText:'Buy 20 rations'}).click();
  await page.locator('#view-realm button', {hasText:'Drill the warband'}).click();
  const preBattle = await page.evaluate(() => ({gold:S.gold,troops:S.army.troops,supplies:S.army.supplies,morale:S.army.morale,combat:S.skills.Combat}));
  await page.locator('#view-realm button', {hasText:'March against bandits'}).click();
  const battle = await page.evaluate(() => ({troops:S.army.troops,supplies:S.army.supplies,morale:S.army.morale,victories:S.army.victories,gold:S.gold,combat:S.skills.Combat}));
  await page.locator('#view-life button', {hasText:'Live another year'}).click();
  const afterYear = await page.evaluate(() => ({year:S.year,gold:S.gold,troops:S.army.troops,morale:S.army.morale}));
  await page.reload();
  const persisted = await page.evaluate(() => ({gender:S.gender,body:S.bodyType,hair:S.hairColor,combat:S.skills.Combat,destruction:S.skills.Destruction,army:S.army,year:S.year}));
  await page.evaluate(() => { localStorage.setItem('ash-oath-save-v1', JSON.stringify({name:'Legacy',gold:17,magic:{Ember:2},skills:{Combat:3}})); });
  await page.reload();
  const migrated = await page.evaluate(() => ({name:S.name,gold:S.gold,skills:S.skills,army:S.army,gender:S.gender,magic:S.magic}));
  return {initial,creatorPresent,skillsPresent,creatorState,preBattle,battle,afterYear,persisted,migrated,errors};
}
